"""Hand-written translations for /agents/ content. Order: zh, en, ja, ko, ms, vi, fr, es, de. zh-Hant derived via OpenCC (s2twp)."""
try:
    import opencc; _cc = opencc.OpenCC('s2twp')
    def _t(s): return _cc.convert(s)
except Exception:
    def _t(s): return s
ORDER = ['zh','en','ja','ko','ms','vi','fr','es','de']
def mk(*v):
    d = dict(zip(ORDER, v)); d['zht'] = _t(d['zh']); return d

